zapi.ts
/**
 * Conexión con el backend de Zapi.
 *
 * Las llamadas se hacen desde el servidor de Next, así que no interviene el
 * navegador y el CORS de la API no aplica. Cada respuesta se revalida sola, de
 * modo que un cambio en Admin aparece aquí sin volver a desplegar. Si la API no
 * responde se devuelve `null` y la sección cae a su contenido por defecto: la
 * landing nunca se cae por un problema del backend.
 */

const API_ORIGIN =
    process.env.ZAPI_API_ORIGIN ?? "https://api.zapisocial.com";

export const APP_URL =
    process.env.NEXT_PUBLIC_APP_URL ?? "https://app.zapisocial.com";

export type SitePlan = {
    id: string;
    slug: string;
    name: string;
    description: string;
    currency: string;
    priceMinor: number;
    billingType: "monthly" | "yearly";
    isFree: boolean;
    featured: boolean;
    trialDays: number;
    position: number;
    permissionIds: string[];
};

export type SiteFaq = { id: string; question: string; answer: string };

export type SitePageSummary = { slug: string; title: string };

export type SiteSettings = {
    siteName: string;
    siteDescription: string;
    companyName: string;
    contactEmail: string;
    contactPhone: string;
    supportHours: string;
    timezone: string;
    dateFormat: string;
    analytics: { measurementId: string } | null;
    registrationEnabled: boolean;
};

export type SiteOverview = {
    settings: SiteSettings;
    languages: { code: string; name: string; nativeName: string }[];
    plans: SitePlan[];
    creditPackages: {
        id: string;
        name: string;
        units: number;
        priceMinor: number;
        currency: string;
    }[];
    faqs: SiteFaq[];
    pages: SitePageSummary[];
};

export type SitePost = {
    slug: string;
    title: string;
    excerpt: string;
    content: string;
    categoryName: string | null;
    publishedAt: string | null;
    tags: string[];
};

export type SitePostsResponse = {
    posts: Omit<SitePost, "content" | "tags">[];
    categories: { slug: string; name: string }[];
    page: number;
    limit: number;
    total: number;
};

export type SitePage = SitePageSummary & { content: string };

async function get<T>(path: string, revalidate = 300): Promise<T | null> {
    try {
        const response = await fetch(`${API_ORIGIN}/v1/public/site${path}`, {
            next: { revalidate },
        });
        if (!response.ok) return null;
        return (await response.json()) as T;
    } catch {
        return null;
    }
}

export const getSite = () => get<SiteOverview>("");
export const getPosts = (query = "") =>
    get<SitePostsResponse>(`/posts${query}`);
export const getPost = (slug: string) =>
    get<SitePost>(`/posts/${encodeURIComponent(slug)}`);
export const getPage = (slug: string) =>
    get<SitePage>(`/pages/${encodeURIComponent(slug)}`);

/** Importe en unidades menores a texto con la moneda del plan. */
export function formatPrice(minor: number, currency: string) {
    return new Intl.NumberFormat("es-EC", {
        currency,
        style: "currency",
        maximumFractionDigits: minor % 100 === 0 ? 0 : 2,
    }).format(minor / 100);
}

/**
 * ¿Hay una sesión válida en este navegador?
 *
 * Solo funciona si la API emite la cookie sobre el dominio raíz
 * (`COOKIE_DOMAIN=.zapisocial.com`); de lo contrario la cookie pertenece a
 * `app.` y aquí no llega. La comprobación se hace en el servidor reenviando la
 * cookie, así que no interviene el navegador ni el CORS. Ante cualquier duda se
 * responde que no hay sesión: mostrar «Empieza gratis» de más es inofensivo,
 * mientras que dar por logueado a quien no lo está no lo es.
 */
export async function hasSession(cookieHeader: string | null): Promise<boolean> {
    if (!cookieHeader?.includes("zapi_session=")) return false;
    try {
        const response = await fetch(`${API_ORIGIN}/v1/auth/session`, {
            headers: { cookie: cookieHeader },
            cache: "no-store",
        });
        return response.ok;
    } catch {
        return false;
    }
}
=== marketing layout ===
import Footer from "@/components/marketing/footer";
import Navbar from "@/components/marketing/navbar";
import { getSite, hasSession } from "@/lib/zapi";
import { headers } from "next/headers";
import React from 'react';

interface Props {
    children: React.ReactNode
}

const MarketingLayout = async ({ children }: Props) => {
    const [signedIn, site] = await Promise.all([
        hasSession((await headers()).get("cookie")),
        getSite(),
    ]);

    return (
        <>
            {/* Las preguntas solo se enlazan si la seccion existe: sin contenido cargado no se renderiza. */}
            <Navbar
                signedIn={signedIn}
                hasFaqs={Boolean(site?.faqs.length)}
                registrationEnabled={site?.settings.registrationEnabled ?? true}
            />
            <main className="mx-auto w-full z-40 relative">
                {children}
            </main>
            <Footer />
        </>
    );
};

export default MarketingLayout
=== root layout ===
import "@/styles/globals.css";
import { cn } from "@/lib";
import { getSite } from "@/lib/zapi";
import { generateMetadata as buildMetadata } from "@/utils";
import { base, heading } from "@/constants";
import { Toaster } from "@/components/ui/sonner";
import { subheading } from "@/constants/fonts";
import Script from "next/script";
import type { Metadata } from "next";

/**
 * El título, la descripción y la analítica salen de la configuración general
 * del Admin. Sin API se conservan los textos por defecto de la plantilla.
 */
export async function generateMetadata(): Promise<Metadata> {
    const site = await getSite();
    const settings = site?.settings;

    return buildMetadata({
        ...(settings?.siteName && settings?.siteDescription
            ? {
                  title: `${settings.siteName} - ${settings.siteDescription}`,
                  description: settings.siteDescription,
              }
            : settings?.siteName
              ? { title: settings.siteName }
              : {}),
    });
}

export default async function RootLayout({
    children,
}: Readonly<{
    children: React.ReactNode;
}>) {
    const site = await getSite();
    const measurementId = site?.settings.analytics?.measurementId;

    return (
        <html lang="es" suppressHydrationWarning>
            <body
                className={cn(
                    "min-h-screen bg-background text-foreground antialiased font-heading overflow-x-hidden !scrollbar-hide",
                    base.variable,
                    heading.variable,
                    subheading.variable,
                )}
            >
                    <Toaster richColors theme="dark" position="top-right" />
                    {children}
                    {measurementId ? (
                        <>
                            <Script
                                src={`https://www.googletagmanager.com/gtag/js?id=${measurementId}`}
                                strategy="afterInteractive"
                            />
                            <Script id="google-analytics" strategy="afterInteractive">
                                {`
                                    window.dataLayer = window.dataLayer || [];
                                    function gtag(){dataLayer.push(arguments);}
                                    gtag('js', new Date());
                                    gtag('config', '${measurementId}');
                                `}
                            </Script>
                        </>
                    ) : null}
            </body>
        </html>
    );
};

