import Wrapper from "@/components/global/wrapper";
import { getPost } from "@/lib/zapi";
import { notFound } from "next/navigation";

type Props = { params: Promise<{ slug: string }> };

export async function generateMetadata({ params }: Props) {
    const { slug } = await params;
    const post = await getPost(slug);
    if (!post) return { title: "Entrada no encontrada | Zapi Social" };
    return { title: `${post.title} | Zapi Social`, description: post.excerpt };
}

const PostPage = async ({ params }: Props) => {
    const { slug } = await params;
    const post = await getPost(slug);
    if (!post) notFound();

    return (
        <Wrapper className="py-20 lg:py-32 relative">
            <Container className="max-w-3xl mx-auto">
                {post.categoryName ? (
                    <span className="text-sm text-accent-foreground/60">
                        {post.categoryName}
                    </span>
                ) : null}
                <h1 className="text-3xl md:text-5xl font-heading font-medium !leading-snug mt-2">
                    {post.title}
                </h1>
                {post.excerpt ? (
                    <p className="text-base md:text-lg text-accent-foreground/80 mt-4">
                        {post.excerpt}
                    </p>
                ) : null}
                <article className="mt-8 whitespace-pre-line text-accent-foreground/90 leading-relaxed">
                    {post.content}
                </article>
            </Container>
        </Wrapper>
    )
};

export default PostPage
