      .map((key) => [key, sortDeep(value[key])])
  )
}

function serialize(block) {
  return JSON.stringify(sortDeep(block), null, 2)
    .split("\n")
    .map((line, index) => (index === 0 ? line : `  ${line}`))
    .join("\n")
}

const anchor = '  "metadata": {'

for (const [file, block] of [
  ["packages/contracts/src/messages/es.json", es],
  ["packages/contracts/src/messages/en.json", en],
]) {
  const raw = readFileSync(file, "utf8")
  if (raw.includes('\n  "marketing": {')) {
    throw new Error(`marketing ya existe en ${file}`)
  }
  if (!raw.includes(`\n${anchor}`)) {
    throw new Error(`no encuentro el ancla en ${file}`)
  }
  const inserted = `  "marketing": ${serialize(block)},\n${anchor}`
  writeFileSync(file, raw.replace(`\n${anchor}`, `\n${inserted}`))
  JSON.parse(readFileSync(file, "utf8"))
  console.log(`marketing añadido a ${file}`)
}

